1	/**
2	 * Configuration-contract test for `release.config.js`, mirroring
3	 * `packageExports.test.ts`'s style: asserts the shape of the manifest
4	 * itself rather than any build output. Confirms the dry-run mode switch
5	 * (`SEMANTIC_RELEASE_DRY_RUN=true`) drops both plugins that require a
6	 * credential, so the PR dry-run job can never accidentally publish. The
7	 * notes-generator block exists because the `conventionalcommits` preset
8	 * major must match the writer major bundled by the stable
9	 * `@semantic-release/release-notes-generator` (preset 10.x needs writer 9;
10	 * the stable plugin ships writer 8), and only rendering real notes catches
11	 * that drift.
12	 */
13	import { afterEach, describe, expect, it } from 'vitest';
14	import { generateNotes } from '@semantic-release/release-notes-generator';
15	import releaseConfig from '../../release.config.js';
16	
17	interface PluginEntry {
18	  0: string;
19	  1?: unknown;
20	}
21	
22	function pluginNames(plugins: unknown[]): string[] {
23	  return (plugins as PluginEntry[]).map((entry) => entry[0]);
24	}
25	
26	describe('release.config.js — configuration contract', () => {
27	  it('branches is exactly ["main"]', () => {
28	    expect(releaseConfig.branches).toEqual(['main']);
29	  });
30	
31	  it('tagFormat is "v${version}"', () => {
32	    expect(releaseConfig.tagFormat).toBe('v${version}');
33	  });
34	
35	  it('normal mode plugin list is commit-analyzer, notes-generator, npm, github in order', () => {
36	    expect(pluginNames(releaseConfig.plugins)).toEqual([
37	      '@semantic-release/commit-analyzer',
38	      '@semantic-release/release-notes-generator',
39	      '@semantic-release/npm',
40	      '@semantic-release/github',
41	    ]);
42	  });
43	
44	  it('the analyzer and the notes generator receive the same parserOpts object identity', () => {
45	    const [, analyzerConfig] = releaseConfig.plugins[0] as [string, { parserOpts: unknown }];
46	    const [, notesConfig] = releaseConfig.plugins[1] as [string, { parserOpts: unknown }];
47	    expect(analyzerConfig.parserOpts).toBe(notesConfig.parserOpts);
48	  });
49	
50	  it('parserOpts.headerCorrespondence is exactly ["type", "scope", "subject"]', () => {
51	    const [, analyzerConfig] = releaseConfig.plugins[0] as [string, { parserOpts: { headerCorrespondence: string[] } }];
52	    expect(analyzerConfig.parserOpts.headerCorrespondence).toEqual(['type', 'scope', 'subject']);
53	  });
54	});
55	
56	describe('release.config.js — dry-run mode', () => {
57	  const originalEnv = process.env.SEMANTIC_RELEASE_DRY_RUN;
58	
59	  afterEach(() => {
60	    if (originalEnv === undefined) {
61	      delete process.env.SEMANTIC_RELEASE_DRY_RUN;
62	    } else {
63	      process.env.SEMANTIC_RELEASE_DRY_RUN = originalEnv;
64	    }
65	  });
66	
67	  it('drops the npm and github plugins, keeping only analyzer and notes-generator', async () => {
68	    process.env.SEMANTIC_RELEASE_DRY_RUN = 'true';
69	    const dryRunModulePath: string = '../../release.config.js?dryrun';
70	    const dryRunConfig = (await import(dryRunModulePath)).default;
71	
72	    expect(pluginNames(dryRunConfig.plugins)).toEqual([
73	      '@semantic-release/commit-analyzer',
74	      '@semantic-release/release-notes-generator',
75	    ]);
76	  });
77	});
78	
79	describe('release.config.js — release notes render under the shipped preset', () => {
80	  const [, notesConfig] = releaseConfig.plugins[1] as [string, { preset: string; parserOpts: Record<string, unknown> }];
81	  const noopLogger = { log() {}, error() {} };
82	
83	  async function render(headers: string[]): Promise<string> {
84	    return generateNotes(notesConfig, {
85	      commits: headers.map((message, index) => ({ hash: String(index).repeat(40), message })),
86	      logger: noopLogger,
87	      cwd: process.cwd(),
